def dump_json_fixed_currency(obj, fp, indent=2):
    def is_currency_key(key):
        return isinstance(key, str) and (key.endswith('_usd') or key == 'switch_threshold_usd')

    def render(value, level=0, key=None):
        pad = ' ' * (indent * level)
        child_pad = ' ' * (indent * (level + 1))
        if isinstance(value, dict):
            if not value:
                return '{}'
            parts = []
            for k, v in value.items():
                parts.append(f"{child_pad}{json.dumps(k)}: {render(v, level + 1, k)}")
            return '{\n' + ',\n'.join(parts) + '\n' + pad + '}'
        if isinstance(value, list):
            if not value:
                return '[]'
            parts = [f"{child_pad}{render(v, level + 1, key)}" for v in value]
            return '[\n' + ',\n'.join(parts) + '\n' + pad + ']'
        if isinstance(value, bool) or value is None:
            return json.dumps(value)
        if isinstance(value, (int, float)):
            if is_currency_key(key):
                return f"{float(value):.2f}"
            return json.dumps(value)
        return json.dumps(value)

    fp.write(render(obj) + '\n')
